B.aCP=new A.eV(B.qU,"\uc815\ub2f5\uc774 \ud558\ub098\ubfd0\uc774\ub77c\ub294 \uc810\uc744 \uc774\uc6a9\ud558\ub294 \uc9c1\uc0ac\uac01\ud615",'\ub124 \uce78\uc774 \ub450 \ubc15\uc2a4\uc5d0 \uac78\uce5c \uc9c1\uc0ac\uac01\ud615\uc774\uace0 \uac19\uc740 \ub450 \uc22b\uc790 {a, b}\ub9cc \ud6c4\ubcf4\ub77c\uba74, \ub124 \uce78\uc758 a\uc640 b\ub97c \uc11c\ub85c \ubc14\uafd4 \uc368\ub3c4 \ubaa8\ub450 \ub9de\uc544\uc11c \uc815\ub2f5\uc774 \ub450 \uac1c\uac00 \ub3fc\uc694 ("\uc8fd\uc740 \ud328\ud134"). \uc815\ub2f5\uc740 \ud558\ub098\ubfd0\uc774\ub2c8 \ud37c\uc990\uc740 \uc774 \ubaa8\uc591\uc744 \ud53c\ud574\uc694. \uc138 \uce78\uc774 {a, b}\ubfd0\uc774\uba74 \ub098\uba38\uc9c0 \ud55c \uce78\uc5d0\uc11c a, b\ub97c \uc9c0\uc6b0\uace0, \ub450 \uce78\uc774 {a, b}\uc774\uace0 \ub2e4\ub978 \ub450 \uce78\uc5d0 \uac19\uc740 \uc22b\uc790 c\uac00 \ub354\ud574\uc838 \uc788\uc73c\uba74 \ub458 \uc911 \ud558\ub098\ub294 \ubc18\ub4dc\uc2dc c\uc608\uc694.',"\ud6c4\ubcf4\uac00 \ub450 \uac1c\ubfd0\uc778 \uce78 \uc14b(\ub610\ub294 \ub458)\uc774 \uc9c1\uc0ac\uac01\ud615\uc73c\ub85c \ub193\uc5ec \uc788\uace0 \uac19\uc740 \ub450 \uc22b\uc790\ub97c \uac00\uc84c\ub294\uc9c0 \ucc3e\uc544\uc694. \uc9c1\uc0ac\uac01\ud615\uc740 \uc815\ud655\ud788 \ub450 \ubc15\uc2a4\uc5d0 \uac78\uccd0\uc57c \ud574\uc694. (\uc815\ub2f5\uc774 \ud558\ub098\uc778 \ud37c\uc990\uc5d0\uc11c\ub9cc \uc4f8 \uc218 \uc788\uc5b4\uc694)",!1,!1)
B.yx=new A.eI(5,"BUG+1",17,"bugPlusOne")
B.aCG=new A.eV(B.yx,"\ubaa8\ub4e0 \uce78\uc774 \ud6c4\ubcf4 \ub450 \uac1c\uc778\ub370 \ud55c \uce78\ub9cc \uc138 \uac1c\uc77c \ub54c","\ube48 \uce78\uc774 \ubaa8\ub450 \ud6c4\ubcf4 \ub450 \uac1c\ubfd0\uc774\uba74 \uc5b4\ub5bb\uac8c \ucc44\uc6cc\ub3c4 \uc815\ub2f5\uc774 \ub458 \uc774\uc0c1\uc774 \ub3fc\uc694 (BUG). \uac70\uae30\uc11c \ub531 \ud55c \uce78\ub9cc \ud6c4\ubcf4\uac00 \uc138 \uac1c\ub77c\uba74 (BUG+1), \uc815\ub2f5\uc774 \ud558\ub098\ubfd0\uc774\ub2c8 \uadf8 \uce78\uc740 BUG\ub97c \uae68\ub294 \uc22b\uc790 \u2014 \ud589\xb7\uc5f4\xb7\ubc15\uc2a4\uc5d0\uc11c \ud6c4\ubcf4\uac00 \uc138 \ubc88 \ub098\uc624\ub294 \uc22b\uc790 \u2014 \uac00 \uc815\ub2f5\uc774\uc5d0\uc694.","\uac8c\uc784 \ub9c9\ubc14\uc9c0\uc5d0 \ube48 \uce78\uc744 \ud6d1\uc5b4\ubcf4\uc138\uc694. \ud6c4\ubcf4\uac00 \uc138 \uac1c\uc778 \uce78\uc774 \ub531 \ud558\ub098\uc774\uace0 \ub098\uba38\uc9c0\uac00 \ubaa8\ub450 \ub450 \uac1c\uc529\uc774\ub77c\uba74, \uadf8 \uce78\uc758 \ud589\xb7\uc5f4\xb7\ubc15\uc2a4\uc5d0\uc11c \ud6c4\ubcf4\uac00 \uc138 \ubc88 \ub098\uc624\ub294 \uc22b\uc790\ub97c \ucc3e\uc544\uc694. \uc815\ub2f5 \ud55c \uce78\uc744 \ub123\uc73c\uba74 \ub3fc\uc694.",!1,!0)
B.yA=new A.eI(6,"XY-\uccb4\uc778",18,"xyChain")
B.aCF=new A.eV(B.yA,"\ud6c4\ubcf4\uac00 \ub450 \uac1c\uc529\uc778 \uce78\ub4e4\uc744 \uc774\uc740 \uae34 \uc0ac\uc2ac",'XY-\uc719\uc744 \uae38\uac8c \ub298\uc778 \uac70\uc608\uc694. \ud6c4\ubcf4\uac00 \ub450 \uac1c\ubfd0\uc778 \uce78\ub4e4\uc744 "\uc11c\ub85c \ubcf4\uace0, \uacb9\uce58\ub294 \uc22b\uc790\uac00 \uc788\ub3c4\ub85d" \uc774\uc5b4\uc694. \uc0ac\uc2ac\uc758 \uccab \uce78\uc774 x\uac00 \uc544\ub2c8\uba74 \uc606 \uce78\uc73c\ub85c \uc22b\uc790\uac00 \ucc28\ub840\ub85c \ub118\uc5b4\uac00 \ub9c8\uc9c0\ub9c9 \uce78\uc774 x\uac00 \ub3fc\uc694. \uadf8\ub7ec\ub2c8 \uc591 \ub05d \uc911 \ud558\ub098\ub294 \ubc18\ub4dc\uc2dc x\uc608\uc694. \uc591 \ub05d\uc774 \ubaa8\ub450 \ubcf4\ub294 \uce78\uc5d0\uc11c\ub294 x\ub97c \uc9c0\uc6b8 \uc218 \uc788\uc5b4\uc694.',"\ud6c4\ubcf4\uac00 \ub450 \uac1c\uc778 \uce78\uc5d0\uc11c \uc2dc\uc791\ud574\uc11c, \uadf8 \uce78\uc774 \ubcf4\ub294 \uce78 \uc911 \ud55c \uc22b\uc790\ub97c \uacf5\uc720\ud558\ub294 \ub450 \ud6c4\ubcf4 \uce78\uc73c\ub85c \uc774\uc5b4 \uac00\uc694. \uc0ac\uc2ac\uc774 \ub2e4\uc2dc \ucc98\uc74c\uc758 x\ub85c \ub05d\ub098\uba74 \ucc3e\uc740 \uac70\uc608\uc694. \uae38\uac8c \uc774\uc5b4\uc9c8\uc218\ub85d \uc5b4\ub824\uc6b0\ub2c8 \ud78c\ud2b8\ub97c \ud65c\uc6a9\ud574 \ubcf4\uc138\uc694.",!1,!1)
B.yF=new A.eI(6,"X-\uccb4\uc778",19,"xChain")
B.aCS=new A.eV(B.yF,"\ud55c \uc22b\uc790\uc758 \uac15\ud55c\xb7\uc57d\ud55c \uc5f0\uacb0\uc744 \ubc88\uac08\uc544 \uc774\uc740 \uc0ac\uc2ac",'\ud55c \uc22b\uc790\uc5d0 \ub300\ud574 "\uadf8 \uc904\uc5d0\uc11c \ub450 \uce78\ubfd0"\uc778 \uc5f0\uacb0(\uac15\ud55c \uc5f0\uacb0: \ud55c\ucabd\uc774 \uc544\ub2c8\uba74 \ub2e4\ub978 \ucabd\uc774 \ubc18\ub4dc\uc2dc)\uacfc "\uc11c\ub85c \ubcf4\ub294 \uce78"\uc758 \uc5f0\uacb0(\uc57d\ud55c \uc5f0\uacb0: \ub458 \ub2e4 \uadf8 \uc22b\uc790\uc77c \uc218\ub294 \uc5c6\uc74c)\uc744 \ubc88\uac08\uc544 \uc774\uc5b4\uc694. \uc0ac\uc2ac\uc758 \uc591 \ub05d\uc740 \ub458 \uc911 \ud558\ub098\uac00 \ubc18\ub4dc\uc2dc \uadf8 \uc22b\uc790\uc608\uc694. \uc591 \ub05d\uc774 \ubaa8\ub450 \ubcf4\ub294 \uce78\uc5d0\uc11c \uadf8 \uc22b\uc790\ub97c \uc9c0\uc6b8 \uc218 \uc788\uc5b4\uc694. \uc2a4\uce74\uc774\uc2a4\ud06c\ub798\ud37c\uc640 \ud22c\uc2a4\ud2b8\ub9c1 \uce74\uc774\ud2b8\ub294 \uc774 \uc0ac\uc2ac\uc774 \uac00\uc7a5 \uc9e7\uc740 \uacbd\uc6b0\uc608\uc694. \uc5ec\ub7ec \uc22b\uc790\ub97c \uc11e\uc5b4 \uc774\uc73c\uba74 AIC(\ubc88\uac08\uc544 \ucd94\ub860 \uccb4\uc778)\uac00 \ub418\uace0, XY-\uccb4\uc778\ub3c4 \uadf8 \ud55c \uac00\uc9c0\uc608\uc694.','\uc22b\uc790 \ud558\ub098\uc5d0\uc11c "\ub450 \uce78\ubfd0\uc778 \uc904"(\uac15\ud55c \uc5f0\uacb0)\ub4e4\uc744 \ucc3e\uace0, \ud55c \uc904\uc758 \ub05d\uacfc \ub2e4\ub978 \uc904\uc758 \ub05d\uc774 \uc11c\ub85c \ubcf4\uba74 \uc774\uc5b4 \uac00\uc694. \uac15\ud55c \uc5f0\uacb0\ub85c \uc2dc\uc791\ud574\uc11c \uac15\ud55c \uc5f0\uacb0\ub85c \ub05d\ub098\uc57c \ud574\uc694.',!1,!1)
B.yB=new A.eI(6,"ALS-XZ",20,"alsXz")
